# source me. t <model> <user> -> status + first 150 chars (never prints tokens)
GWURL=${GWURL:-http://localhost:18000}
tok() { MICRON_USER=$1 MICRON_PASSWORD_GRANT=1 python3 "$(dirname "${BASH_SOURCE[0]}")/../clients/okta_token.py"; }
t() { local m=$1 u=$2 tk; tk=$(tok "$u"); printf "%-26s %-6s " "$m" "$u"; curl -s -m ${TMAX:-40} -o /tmp/r.out -w "%{http_code} " "$GWURL${GWPATH:-/anthropic}/v1/messages" -H "authorization: Bearer $tk" -H "anthropic-version: 2023-06-01" -H 'content-type: application/json' -d "{\"model\":\"$m\",\"max_tokens\":16,\"messages\":[{\"role\":\"user\",\"content\":\"Say hi\"}]}"; head -c 130 /tmp/r.out | tr '\n' ' '; echo; }
# p <user> <path-prefix> "<prompt>" -> status + body head (for security tests)
p() { local u=$1 pre=$2 txt=$3 tk; tk=$(tok "$u"); printf "%-6s " "$u"; curl -s -m ${TMAX:-40} -o /tmp/r.out -w "%{http_code} " "$GWURL$pre/v1/messages" -H "authorization: Bearer $tk" -H "anthropic-version: 2023-06-01" -H 'content-type: application/json' -d "$(jq -n --arg t "$txt" '{model:"claude-haiku-5-5",max_tokens:16,messages:[{role:"user",content:$t}]}')"; head -c ${HEADN:-260} /tmp/r.out | tr '\n' ' '; echo; }
# ask <user> <path-prefix> "<prompt>" [model] -> prints status and the answer text (max 400 chars)
ask() { local u=$1 pre=$2 txt=$3 m=${4:-claude-sonnet-5-5} tk; tk=$(tok "$u"); printf "%-6s " "$u"; curl -s -m ${TMAX:-60} -o /tmp/a.out -w "%{http_code} " "$GWURL$pre/v1/messages" -H "authorization: Bearer $tk" -H "anthropic-version: 2023-06-01" -H 'content-type: application/json' -d "$(jq -n --arg t "$txt" --arg m "$m" '{model:$m,max_tokens:300,messages:[{role:"user",content:$t}]}')"; jq -r '([.content[]?|select(.type=="text")|.text]|join(" ")) // .error.message' /tmp/a.out | tr '\n' ' ' | cut -c1-${ANSN:-400}; echo; }
